@pytest.mark.parametrize("worker", [False, True]) @pytest.mark.parametrize("redirect", [False, True]) def test_cookie_only_login_rotation_scope_and_terminal_replay(tmp_path, worker, redirect): with cookie_target(redirect) as (url, events, values): credentials, tasks, policy = CredentialManager(), campaign_tasks(url), ExecutionPolicy(max_workers=3, max_retries=0) if worker: store = InMemorySessionStore() coordinator = ApiSubagentCoordinator(pool=ApiTaskPool(tasks), policy=policy, coordinator_runtime_service=ControlledWorkerLauncher(store), session_store=store, parent_context={"session_id": "parent", "turn_id": "turn"}, credential_manager=credentials) else: coordinator = ApiTestCoordinator(pool=ApiTaskPool(tasks), policy=policy, executor_fn=ApiTaskExecutor(credential_manager=credentials).execute) result = asyncio.run(coordinator.run_all()) before = [task.model_dump(mode="json") for task in result] count = len(events) asyncio.run(coordinator.run_all()) assert before == [task.model_dump(mode="json") for task in result] and len(events) == count report = ReportBuilder().build(campaign=ApiTestCampaign(campaign_id="cookie", tasks=result)) facts = {"events": events, "statuses": [t.status for t in result], "report": report.model_dump(mode="json"), "external_ai_calls": 0, "terminal_extra_http": len(events)-count} directory = Path(os.getenv("QA_API_COOKIE_DIR", str(tmp_path))) directory.mkdir(parents=True, exist_ok=True) raw = json.dumps(facts, ensure_ascii=False, indent=2) assert all(value not in raw for value in values.values()) (directory/f"{'worker' if worker else 'inline'}-{'redirect' if redirect else 'direct'}.json").write_text(raw, encoding="utf8") > assert all(t.status == "completed" for t in result), facts E AssertionError: {'events': [{'method': 'POST', 'path': '/api/login', 'cookie_names': [], 'sid_source': 'absent'}, {'method': 'POST', '...failed, 4 skipped. Checks: 1 passed, 1 failed. Total time: 82ms.", 'total_tasks': 6, ...}, 'external_ai_calls': 0, ...} E assert